/**
 * An EXISTS / NOT EXISTS / IN / ANY / ALL subquery depends on every variable it <em>references</em>, not only on the
 * variables its body can bind. Liveness-driven rewrites (unused-OPTIONAL pruning, projection-below-ORDER) must keep an
 * optional binding alive when the subquery's inner FILTER reads it.
 */
class PackedExistsReferencedDependenciesTest {

	private static final String OPTIONAL_WITH_EXISTS_INNER_FILTER = "?s :p ?v OPTIONAL { ?s :q ?b } "
			+ "FILTER EXISTS { ?s :r ?c FILTER(?c = ?b) }";

	@Test
	void projectionBelowOrderKeepsBindingObservedByExistsInOrderKey() {
		Model data = model();
		add(data, "a", "p", VF.createLiteral(1));
		add(data, "a", "q", iri("z"));
		add(data, "a", "r", iri("k"));
		add(data, "b", "p", VF.createLiteral(2));
		add(data, "b", "q", iri("k"));
		add(data, "b", "r", iri("k"));
		assertPackedPlanPreservesResults(data,
				"SELECT ?s WHERE { ?s :p ?v OPTIONAL { ?s :q ?b } } ORDER BY DESC(EXISTS { ?s :r :k FILTER(?b = :k) }) ?s LIMIT 1",
				SUBJECT_LOOKUP_COSTS, null, List.of("s=urn:t:b"));
	}

	@Test
	void distinctKeepsOptionalObservedByExistsInnerFilter() {
		assertFalse(generates(parse("SELECT DISTINCT ?s WHERE { " + OPTIONAL_WITH_EXISTS_INNER_FILTER + " }"),
				PackedRuleProofs.REMOVE_UNUSED_OPTIONAL),
				"the EXISTS inner FILTER reads the optional ?b, so the OPTIONAL is observed and must be kept");
	}

	@Test
	void reducedKeepsOptionalObservedByExistsInnerFilter() {
		assertFalse(generates(parse("SELECT REDUCED ?s WHERE { " + OPTIONAL_WITH_EXISTS_INNER_FILTER + " }"),
				PackedRuleProofs.REMOVE_UNUSED_OPTIONAL));
	}

	@Test
	void distinctKeepsOptionalObservedByNotExistsInnerFilter() {
		assertFalse(generates(parse("SELECT DISTINCT ?s WHERE { ?s :p ?v OPTIONAL { ?s :q ?b } "
				+ "FILTER NOT EXISTS { ?s :r ?c FILTER(?c = ?b) } }"), PackedRuleProofs.REMOVE_UNUSED_OPTIONAL));
	}

	@Test
	void countDistinctKeepsOptionalObservedByExistsInnerFilter() {
		assertFalse(generates(
				parse("SELECT (COUNT(DISTINCT ?s) AS ?n) WHERE { " + OPTIONAL_WITH_EXISTS_INNER_FILTER + " }"),
				PackedRuleProofs.REMOVE_UNUSED_OPTIONAL));
	}

	@Test
	void distinctStillPrunesOptionalWhenExistsReferencesOnlyAssuredVariables() {
		assertTrue(generates(parse("SELECT DISTINCT ?s WHERE { ?s :p ?v OPTIONAL { ?s :q ?b } "
				+ "FILTER EXISTS { ?s :r ?c } }"), PackedRuleProofs.REMOVE_UNUSED_OPTIONAL),
				"an EXISTS that never reads ?b must not block pruning of the unobserved OPTIONAL");
	}

	@Test
	void distinctKeepsOptionalObservedByInSubquery() {
		Projection subquery = existsBodyProjection();
		assertFalse(generates(distinctOverOptional(new In(Var.of("v"), subquery)),
				PackedRuleProofs.REMOVE_UNUSED_OPTIONAL));
	}

	@Test
	void distinctKeepsOptionalObservedByCompareAnySubquery() {
		Projection subquery = existsBodyProjection();
		assertFalse(generates(
				distinctOverOptional(new CompareAny(Var.of("v"), subquery, Compare.CompareOp.EQ)),
				PackedRuleProofs.REMOVE_UNUSED_OPTIONAL));
	}

	@Test
	void projectionBelowOrderDeclinesWhenOrderExistsReferencesProjectedAwayBinding() {
		assertFalse(generates(parse("SELECT ?s WHERE { ?s :p ?v OPTIONAL { ?s :q ?b } } "
				+ "ORDER BY DESC(EXISTS { ?s :r :k FILTER(?b = :k) }) ?s"), PackedRuleProofs.PROJECTION_BELOW_ORDER),
				"the ORDER key EXISTS reads ?b which the projection drops");
	}

	@Test
	void projectionBelowOrderAppliesWhenOrderExistsReferencesOnlyLocalAndProjectedBindings() {
		assertTrue(generates(parse("SELECT ?s WHERE { ?s :p ?v } ORDER BY DESC(EXISTS { ?s :r ?c }) ?s"),
				PackedRuleProofs.PROJECTION_BELOW_ORDER),
				"?c is EXISTS-local (the ORDER input cannot bind it) and ?s is projected, so the push is sound");
	}

	private static Projection existsBodyProjection() {
		StatementPattern probe = new StatementPattern(Var.of("s"), Var.of("r", iri("r")), Var.of("c"));
		Filter inner = new Filter(probe, new Compare(Var.of("c"), Var.of("b"), Compare.CompareOp.EQ));
		return new Projection(inner, new ProjectionElemList(new ProjectionElem("c")));
	}

	private static TupleExpr distinctOverOptional(ValueExpr condition) {
		StatementPattern base = new StatementPattern(Var.of("s"), Var.of("p", iri("p")), Var.of("v"));
		StatementPattern optional = new StatementPattern(Var.of("s"), Var.of("q", iri("q")), Var.of("b"));
		Filter filter = new Filter(new LeftJoin(base, optional), condition);
		Projection projection = new Projection(filter, new ProjectionElemList(new ProjectionElem("s")));
		return new QueryRoot(new Distinct(projection));
	}
}
